package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
import io.knowledgebrain.contracts.collaboration.resubmissionrequest.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class ResubmissionRequestStoreIntegrationTest {
 SubmissionStoreIntegrationTest f;ResubmissionRequestStore store;SubmissionStore.Submission answer;
 @BeforeEach void setup(){f=new SubmissionStoreIntegrationTest();f.setup();f.open();answer=f.submit(f.f.key(),0,2,"Original answer").submission();store=new ResubmissionRequestStore(f.f.source,f.parent.store,Clock.systemUTC());}
 ResubmissionRequestStore.Request change(long expected,long source,String reason){return store.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,expected,new ResubmissionRequestInput("REQUEST",reason,source,2),f.f.trace);}
 ResubmissionRequestStore.Request cancel(long expected){return store.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,expected,new ResubmissionRequestInput("CANCEL",null,0,0),f.f.trace);}
 ResubmissionRequestStore.View get(UUID actor,boolean owner){return store.get(f.group,f.space,f.study,f.assignment,answer.submissionId(),actor,owner);}
 ResubmissionRequestStore.History history(long before,int limit){return store.history(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false,before,limit);}
 void status(int code,org.junit.jupiter.api.function.Executable action){f.status(code,action);}
 @Test void absentReadDoesNotCreateAnythingAndPeersCannotDiscoverAbsence(){var v=get(f.author,false);assertNull(v.request());assertFalse(v.canRequest());assertFalse(v.canCancel());assertTrue(get(f.f.owner,true).canRequest());assertTrue(history(Long.MAX_VALUE,5).items().isEmpty());status(404,()->get(f.f.ids.next(),false));status(409,()->cancel(0));assertNull(get(f.author,false).request());}
 @Test void requestPinsAnswerAndFullProtobufWithIndependentVersion()throws Exception{var v=change(0,1,"Explain <script>\n수정 근거");assertEquals(7,v.requestId().version());assertEquals("REQUESTED",v.state());assertNull(v.resolvedSubmissionVersion());assertEquals(f.f.owner,v.requestedBy());assertEquals(f.f.owner,v.changedBy());assertEquals(f.author,v.authorId());assertEquals(1,v.version());assertEquals(1,v.submissionVersion());assertEquals(2,v.assignmentVersion());assertEquals(v,history(Long.MAX_VALUE,5).items().getFirst().snapshot());assertEquals(answer,f.store.get(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false));assertEquals(2,f.parent.store.get(f.group,f.space,f.study,f.assignment).version());assertEquals(1,f.events(answer.submissionId()));
  var e=ResubmissionRequestEnvelopeV1.parseFrom(f.f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.requestId()));var p=ResubmissionRequestSnapshotV1.parseFrom(e.getPayload());assertEquals("ResubmissionRequested",e.getEventType());assertEquals(f.f.trace,e.getTraceId());assertEquals(f.space.toString(),e.getSpaceId());assertEquals(f.f.owner.toString(),e.getActorId());assertEquals(v.reason(),p.getReason());assertFalse(p.hasResolvedSubmissionVersion());assertEquals("AUTHOR_AND_OWNER",p.getAudience());}
 @Test void exactNoOpStaysStableButStaleSameValueFails(){var v=change(0,1,"First reason");assertEquals(v,change(1,1,"First reason"));status(412,()->change(0,1,"First reason"));var corrected=change(1,1,"Corrected reason");assertEquals(v.requestId(),corrected.requestId());assertEquals(v.createdAt(),corrected.createdAt());assertEquals(2,corrected.version());assertEquals(2,f.events(v.requestId()));}
 @Test void newAttemptResolvesRequestInSameTransactionAndOldRetryCannotResolveNewRequest(){String key=f.f.key();var first=change(0,1,"First request");var second=f.submit(key,1,2,"Second answer").submission();var resolved=get(f.author,false).request();assertEquals("RESOLVED",resolved.state());assertEquals(2L,resolved.resolvedSubmissionVersion());assertEquals(1,resolved.submissionVersion());assertEquals(f.author,resolved.changedBy());assertEquals(first.requestedBy(),resolved.requestedBy());assertEquals(2,resolved.version());assertFalse(get(f.f.owner,true).canCancel());var newRequest=change(2,2,"Review second answer");assertFalse(f.submit(key,1,2,"Second answer").applied());assertEquals(newRequest,get(f.author,false).request());assertEquals(second,f.store.mine(f.group,f.space,f.study,f.assignment,f.author,true).submission());status(412,()->cancel(2));}
 @Test void cancelIsAuditedAndDoesNotResolveOnLaterAnswer(){var v=change(0,1,"Reason");var cancelled=cancel(1);assertEquals("CANCELLED",cancelled.state());assertEquals(2,cancelled.version());assertEquals(v.reason(),cancelled.reason());assertEquals(cancelled,cancel(2));f.submit(f.f.key(),1,2,"New answer after cancellation");assertEquals(cancelled,get(f.author,false).request());assertEquals(2,f.events(v.requestId()));assertEquals(3,change(2,2,"Request latest").version());}
 @Test void staleReviewedAnswerAndWrongOriginalInstructionsAreRejected(){change(0,1,"Request original");f.submit(f.f.key(),1,2,"New answer");status(409,()->change(2,1,"Stale review"));status(409,()->store.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,2,new ResubmissionRequestInput("REQUEST","Wrong instruction",2,3),f.f.trace));assertEquals(2,get(f.author,false).request().version());}
 @Test void instructionsArePinnedToSubmittedRevisionAfterMetadataEdits(){f.parent.store.metadata(f.group,f.space,f.study,f.assignment,f.f.owner,2,"New instructions","Details",f.f.trace);assertEquals(2,change(0,1,"Original instruction basis").assignmentVersion());assertEquals(3,f.parent.store.get(f.group,f.space,f.study,f.assignment).version());}
 @Test void closedAssignmentCannotRequestOrResubmitButCanCancelPending(){var v=change(0,1,"Pending before close");f.parent.store.state(f.group,f.space,f.study,f.assignment,f.f.owner,2,"CLOSED",f.f.trace);assertFalse(get(f.f.owner,true).canRequest());assertTrue(get(f.f.owner,true).canCancel());status(409,()->change(1,1,"After close"));status(409,()->f.submit(f.f.key(),1,3,"Forbidden after close"));assertEquals(v,get(f.author,false).request());assertEquals("CANCELLED",cancel(1).state());}
 @Test void archivedParentsFreezeRequestsButKeepHistory(){var v=change(0,1,"Pending");f.parent.parent.store.state(f.group,f.space,f.study,f.f.owner,1,"RETIRED",f.f.trace);assertFalse(get(f.f.owner,true).canCancel());assertFalse(get(f.f.owner,true).canRequest());status(409,()->cancel(1));status(409,()->change(1,1,"Frozen"));assertEquals(v,history(Long.MAX_VALUE,5).items().getFirst().snapshot());}
 @Test void retainedHistoryAndWrongScopeNeverBypassAuthorPrivacy(){change(0,1,"Private");UUID peer=f.f.ids.next();status(404,()->store.history(f.group,f.space,f.study,f.assignment,answer.submissionId(),peer,false,Long.MAX_VALUE,5));status(404,()->store.get(f.f.ids.next(),f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,true));status(404,()->store.get(f.group,f.f.ids.next(),f.study,f.assignment,answer.submissionId(),f.f.owner,true));status(404,()->store.get(f.group,f.space,f.study,f.f.ids.next(),answer.submissionId(),f.f.owner,true));status(404,()->store.change(f.group,f.space,f.study,f.assignment,f.f.ids.next(),f.f.owner,0,new ResubmissionRequestInput("REQUEST","Wrong ID",1,2),f.f.trace));}
 @Test void paginatedAuditKeepsEveryCorrectionAndCancellation(){for(int n=0;n<6;n++)change(n,1,"Reason "+n);cancel(6);var a=history(Long.MAX_VALUE,5);assertEquals(List.of(7L,6L,5L,4L,3L),a.items().stream().map(ResubmissionRequestStore.Revision::version).toList());assertEquals(3L,a.nextBefore());var b=history(a.nextBefore(),5);assertEquals(List.of(2L,1L),b.items().stream().map(ResubmissionRequestStore.Revision::version).toList());assertNull(b.nextBefore());assertEquals("REQUESTED",b.items().getLast().snapshot().state());}
 @Test void concurrentFirstAndExistingCommandsHaveOnlyOneWinner()throws Exception{try(var pool=Executors.newVirtualThreadPerTaskExecutor()){for(int round=0;round<2;round++){long base=round;var barrier=new CyclicBarrier(2);var futures=new ArrayList<Future<Boolean>>();for(int n=0;n<2;n++){String reason="Reason "+round+"/"+n;futures.add(pool.submit(()->{barrier.await();try{change(base,1,reason);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));}assertNotEquals(futures.get(0).get(20,TimeUnit.SECONDS),futures.get(1).get(20,TimeUnit.SECONDS));}}}
 @Test void racingRequestAndNewAnswerNeverLeavesPendingOldAnswer()throws Exception{try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var a=pool.submit(()->{barrier.await();return f.submit(f.f.key(),1,2,"Racing new answer");});var b=pool.submit(()->{barrier.await();try{return change(0,1,"Review old");}catch(ResponseStatusException e){assertEquals(409,e.getStatusCode().value());return null;}});assertEquals(2,a.get(20,TimeUnit.SECONDS).submission().version());var requested=b.get(20,TimeUnit.SECONDS);var current=get(f.author,false).request();if(requested==null)assertNull(current);else{assertEquals("RESOLVED",current.state());assertEquals(2L,current.resolvedSubmissionVersion());}}}
 @Test void requestOutboxFailureRollsBackAnswerAndBothAudits(){var initial=change(0,1,"Pending");String name="request_fail_"+answer.submissionId().toString().replace("-","");f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+" CHECK(aggregatetype<>'resubmission-request' OR trace_id<>'"+f.f.trace+"') NOT VALID");try{assertThrows(RuntimeException.class,()->f.submit(f.f.key(),1,2,"Must roll back"));assertEquals(answer,f.store.mine(f.group,f.space,f.study,f.assignment,f.author,true).submission());assertEquals(1,f.store.history(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false,Long.MAX_VALUE,5).items().size());assertEquals(initial,get(f.author,false).request());assertEquals(1,history(Long.MAX_VALUE,5).items().size());assertEquals(1,f.events(answer.submissionId()));assertThrows(RuntimeException.class,()->cancel(1));assertEquals(initial,get(f.author,false).request());}finally{f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}assertEquals(2,f.submit(f.f.key(),1,2,"Works after recovery").submission().version());assertEquals("RESOLVED",get(f.author,false).request().state());}
 @Test void databaseChecksBothSourceAndResolutionProvenance(){var v=change(0,1,"Source");assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.jdbc.update("UPDATE resubmission_request SET submission_version=999999 WHERE request_id=?",v.requestId()));assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.jdbc.update("UPDATE resubmission_request SET resolved_submission_version=1 WHERE request_id=?",v.requestId()));assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.jdbc.update("UPDATE resubmission_request SET resolved_submission_version=999999 WHERE request_id=?",v.requestId()));assertEquals(v,get(f.author,false).request());}
}
